class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<long long, int> seen;
        seen[0] = 1;
        long long prefix = 0;
        int count = 0;
        for (int x : nums) {
            prefix += x;
            count += seen[prefix - k];
            seen[prefix]++;
        }
        return count;
    }
};
